var DATA = {"mode": "percore", "cores": [55, 58, 56, 60, 54, 57, 59, 56]};
function show(k,v){console.log(k+": "+v);}
var m=DATA.mode;
if(m==="percore"){
  console.log("Per-core temps:");
  DATA.cores.forEach(function(t,i){console.log("  Core "+i+": "+t+" C");});
  show("Hottest core",Math.max.apply(null,DATA.cores)+" C");
}else if(m==="tjmax"){
  var d=DATA.tjmax-DATA.temp;
  show("TjMax",DATA.tjmax+" C");show("Current",DATA.temp+" C");
  show("Distance to TjMax",d+" C");
  show("Status",d>20?"comfortable":(d>5?"warm":"CRITICAL"));
}else if(m==="coretemp"){
  show("Tool","CoreTemp - per-core DTS readings");
  show("Hottest",DATA.hot+" C");show("Coolest",DATA.low+" C");
}else if(m==="ohm"){
  show("Tool","Open Hardware Monitor - open-source sensor tree");
  show("Sensors",DATA.n+" across CPU, GPU, board, drives");
}else if(m==="fork"){
  show("Original","Open Hardware Monitor");
  show("Maintained fork","LibreHardwareMonitor - actively updated");
  show("Advice","use the fork on modern hardware");
}else if(m==="wmi"){
  show("Interface","WMI - other apps query sensors");
  show("Use","scripts, widgets, and remote dashboards");
}else if(m==="gadget"){
  show("Desktop gadget","live temps on the desktop");
  show("Taskbar","per-core icons always visible");
}else if(m==="log"){
  show("Log",DATA.file);show("Interval",DATA.ms+" ms");
}else if(m==="overheat"){
  show("Protection","at "+DATA.th+" C -> "+DATA.action);
}else if(m==="plugin"){
  show("Plugins",DATA.n+" available");
  show("Examples","remote server, Logitech G15 applet");
}else if(m==="tray"){
  show("Taskbar","hottest core temp always visible");
  show("Why","glanceable during fullscreen games");
  show("Now",DATA.now+" C");
}else if(m==="delta"){
  show("Core 0",DATA.a+" C");show("Core 5",DATA.b+" C");
  show("Spread",Math.abs(DATA.a-DATA.b)+" C");
  show("Note","big spreads hint at cooler mount issues");
}else if(m==="compare"){
  show("CoreTemp","tiny, per-core focused, plugin ecosystem");
  show("OHM / Libre","full sensor tree, open source, WMI");
}else if(m==="workflow"){
  console.log("Temp-watch workflow:");
  DATA.steps.forEach(function(s,i){console.log("  "+(i+1)+". "+s);});
}
